<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_risks.manage');$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$risk=null;if($id){$q=$pdo->prepare('SELECT * FROM project_risks WHERE id=?');$q->execute([$id]);$risk=$q->fetch();if(!$risk){http_response_code(404);exit('Riesgo no encontrado.');}}$projectId=(int)($_GET['project_id']??$_POST['project_id']??($risk['project_id']??0));$projects=pm_project_options($pdo);$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle=$risk?'Editar riesgo':'Nuevo riesgo';$v=fn($k,$d='')=>$_POST[$k]??($risk[$k]??$d);$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));if($title==='')$errors[]='Título obligatorio.';$projectId=(int)($_POST['project_id']??0);if(!$projectId)$errors[]='Selecciona un proyecto.';if(!$errors){$data=[$projectId,$title,trim((string)($_POST['description']??''))?:null,trim((string)($_POST['category']??''))?:null,max(0,min(100,(int)($_POST['probability']??20))),max(0,min(100,(int)($_POST['impact']??20))),(string)($_POST['status']??'open'),(int)($_POST['owner_user_id']??0)?:null,trim((string)($_POST['mitigation']??''))?:null,($_POST['due_date']??'')?:null];if($id)$pdo->prepare('UPDATE project_risks SET project_id=?,title=?,description=?,category=?,probability=?,impact=?,status=?,owner_user_id=?,mitigation=?,due_date=? WHERE id=?')->execute([...$data,$id]);else{$pdo->prepare('INSERT INTO project_risks(project_id,title,description,category,probability,impact,status,owner_user_id,mitigation,due_date,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([...$data,(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();}pm_recalculate_project($pdo,$projectId);flash('success','Riesgo guardado.');redirect('project_risks.php?project_id='.$projectId);}}require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><h2><?=$risk?'Editar riesgo':'Nuevo riesgo'?></h2><a class="btn btn-light btn-small" href="project_risks.php?project_id=<?=$projectId?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Proyecto<select name="project_id"><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Categoría<input name="category" value="<?=e($v('category'))?>" placeholder="Alcance, técnico, cliente..."></label><label class="full">Riesgo *<input name="title" required value="<?=e($v('title'))?>"></label><label>Probabilidad %<input type="number" min="0" max="100" name="probability" value="<?=e($v('probability',20))?>"></label><label>Impacto %<input type="number" min="0" max="100" name="impact" value="<?=e($v('impact',20))?>"></label><label>Estado<select name="status"><?php foreach(['open'=>'Abierto','mitigating'=>'Mitigando','accepted'=>'Aceptado','closed'=>'Cerrado'] as$k=>$lab):?><option value="<?=$k?>" <?=$v('status','open')===$k?'selected':''?>><?=$lab?></option><?php endforeach;?></select></label><label>Responsable<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('owner_user_id')===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Fecha objetivo<input type="date" name="due_date" value="<?=e($v('due_date'))?>"></label><label class="full">Descripción<textarea name="description"><?=e($v('description'))?></textarea></label><label class="full">Plan de mitigación<textarea name="mitigation"><?=e($v('mitigation'))?></textarea></label><div class="full form-actions"><button class="btn btn-primary">GUARDAR RIESGO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
